<?php declare(strict_types=1); namespace Database\Schema; use Core\Database\Schema\Blueprint; use Core\Database\Schema\SchemaDefinition; class UserRolesSchema extends SchemaDefinition { protected string $table = 'user_roles'; public function define(Blueprint $table): void { $table->id(); $table->foreignId('user_id'); $table->foreignId('role_id'); $table->timestamps(); $table->foreign('user_id')->references('id')->on('users')->onDelete('CASCADE'); $table->foreign('role_id')->references('id')->on('roles')->onDelete('CASCADE'); $table->unique('user_id', 'role_id'); } } 